 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  using namespace sqlgen;

  // Connect to the SQLite database "test_db.sqlite"
  auto result = sqlite::connect("test_db.sqlite")
    // Drop the table if it exists
    .and_then([](auto conn) {
      return (drop<Product> | if_exists)(conn).transform([conn](auto) {
        return conn;
      });
    })
    // Begin transaction
    .and_then(begin_transaction)
    // Create the Product table
    .and_then(create_table<Product>)
    // Insert the products into the database
    .and_then(insert(products))
    // Commit the transaction if all inserts succeed
    .and_then(commit);

  // Return true if successful, false otherwise
  return result.has_value();
}

}  // namespace batch_insert_products
```

