   108→                  sql.size(),  /* Maximum length of zSql in bytes. */
   109→                  &p_stmt,     /* OUT: Statement handle */
   110→                  nullptr      /* OUT: Pointer to unused portion of zSql */
   111→  );
   112→
   113→  if (!p_stmt) {
   114→    return error(sqlite3_errmsg(conn_.get()));
   115→  }
   116→
   117→  return Ref<sqlite3_stmt>::make(StmtPtr(p_stmt, &sqlite3_finalize))
   118→      .transform([&](auto _stmt) -> Ref<IteratorBase> {
   119→        return Ref<Iterator>::make(_stmt, conn_);
   120→      });
