   124→    const std::string& _sql) const noexcept {
   125→  sqlite3_stmt* p_stmt = nullptr;
   126→
   127→  sqlite3_prepare(conn_.get(),  /* Database handle */
   128→                  _sql.c_str(), /* SQL statement, UTF-8 encoded */
   129→                  _sql.size(),  /* Maximum length of zSql in bytes. */
   130→                  &p_stmt,      /* OUT: Statement handle */
   131→                  nullptr       /* OUT: Pointer to unused portion of zSql */
   132→  );
   133→
   134→  if (!p_stmt) {
   135→    return error("Preparing the following statement failed: " + _sql +
   136→                 " Reason: " + sqlite3_errmsg(conn_.get()));
   137→  }
   138→
