```cpp
#pragma once

#include <optional>
#include <string>
#include <vector>

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace query_course_enrollment_stats {

using namespace sqlgen;
using namespace sqlgen::literals;

struct Course {
  PrimaryKey<int> course_id;
  std::string title;
};

struct Enrollment {
  PrimaryKey<int> enrollment_id;
  ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

/**
 * Description: This function calculates enrollment statistics per course, including the number of students and the average grade.
 * Returns: std::vector<CourseStats>.
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  // Build the query: LEFT JOIN Course and Enrollment, GROUP BY course
  const auto get_stats =
      select_from<Course, "c">(
          "title"_c | as<"title">,
          count("enrollment_id"_e) | as<"student_count">,
          avg("grade"_e) | as<"avg_grade">) |
      left_join<Enrollment, "e">("course_id"_c == "course_id"_e) |
      group_by("course_id"_c, "title"_c) |
      to<std::vector<CourseStats>>;

  // Connect to the database and execute the query
  return sqlite::connect("test_db.sqlite")
      .and_then(get_stats)
      .value();
}

}  // namespace query_course_enrollment_stats
```

## Explanation:

1. **Includes**: Added the necessary sqlgen headers (`sqlgen.hpp` and `sqlgen/sqlite.hpp`)

2. **Using directives**: Added `using namespace sqlgen` and `using namespace sqlgen::literals` to access sqlgen functions and the literal suffix operators (like `"title"_c`)

3. **Query construction**:
   - `select_from<Course, "c">`: Select from the Course table with alias "c"
   - Selected columns:
     - `"title"_c | as<"title">`: Course title
     - `count("enrollment_id"_e) | as<"student_count">`: Count of enrollment IDs (student count)
     - `avg("grade"_e) | as<"avg_grade">`: Average grade (automatically ignores NULLs)
   - `left_join<Enrollment, "e">`: LEFT JOIN with Enrollment table aliased as "e"
   - Join condition: `"course_id"_c == "course_id"_e`
   - `group_by("course_id"_c, "title"_c)`: Group by course ID and title
   - `to<std::vector<CourseStats>>`: Convert results to the CourseStats vector

4. **Database connection**: Uses `sqlite::connect("test_db.sqlite")` to connect to the specified database file

5. **Execution**: The query is executed via `.and_then(get_stats).value()`, which returns the results as a vector

This implementation matches the reference SQL query and properly handles NULL grades (the `avg()` function in SQL automatically excludes NULL values).

