namespace query_course_enrollment_stats {

using namespace sqlgen;
using namespace sqlgen::literals;

struct Course {
  PrimaryKey<int> course_id;
  std::string title;
};

struct Enrollment {
  PrimaryKey<int> enrollment_id;
  ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

/**
 * Description: This function calculates enrollment statistics per course, including the number of students and the average grade.
 * Returns: std::vector<CourseStats>.
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  // Build the query: LEFT JOIN Course and Enrollment, GROUP BY course
  const auto get_stats =
      select_from<Course, "c">(
          "title"_c | as<"title">,
          count("enrollment_id"_e) | as<"student_count">,
          avg("grade"_e) | as<"avg_grade">) |
      left_join<Enrollment, "e">("course_id"_c == "course_id"_e) |
      group_by("course_id"_c, "title"_c) |
      to<std::vector<CourseStats>>;

  // Connect to the database and execute the query
  return sqlite::connect("test_db.sqlite")
      .and_then(get_stats)
      .value();
}

}  // namespace query_course_enrollment_stats

