#pragma once

#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_daily_traffic_metrics {

struct PageVisit {
  sqlgen::PrimaryKey<int> visit_id;
  std::string url;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> visit_time;
};

struct DailyTraffic {
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the database
  const auto conn = sqlite::connect("test_db.sqlite");

  // Build the query to extract date, count visits, and count unique URLs
  const auto query = select_from<PageVisit>(
      cast<std::string>(cast<Date>("visit_time"_c)) | as<"visit_date">,
      count() | as<"total_visits">,
      count_distinct("url"_c) | as<"unique_pages">
  ) | group_by(cast<std::string>(cast<Date>("visit_time"_c)))
    | order_by(cast<std::string>(cast<Date>("visit_time"_c)))
    | to<std::vector<DailyTraffic>>;

  // Execute the query and return the result
  return conn.and_then(query).value();
}

}  // namespace query_daily_traffic_metrics
```

