#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <optional>
#include <string>
#include <vector>

namespace query_employee_hierarchy {

struct Employee {
  sqlgen::PrimaryKey<int> emp_id;
  std::string name;
  std::optional<int> manager_id;
};

struct EmployeeManager {
  std::string employee;
  std::optional<std::string> manager;
};

/**
 * Description: retrieve employee details along with their manager's name using a left join.
 * Returns: std::vector<EmployeeManager>, where each struct contains the employee's name and their manager's name (if any).
 */
std::vector<EmployeeManager> query_employee_hierarchy() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Build the query: SELECT e1.name as employee, e2.name as manager
    // FROM Employee e1 LEFT JOIN Employee e2 ON e1.manager_id = e2.emp_id
    const auto query =
        select_from<Employee, "e1">(
            "name"_e1 | as<"employee">,
            "name"_e2 | as<"manager">
        ) |
        left_join<Employee, "e2">("manager_id"_e1 == "emp_id"_e2) |
        to<std::vector<EmployeeManager>>;

    // Connect to the database and execute the query
    auto result = sqlite::connect("test_db.sqlite")
                      .and_then(query)
                      .value();

    return result;
}

}  // namespace query_employee_hierarchy
```

## How it works:

1. **Self-Join Setup**: Uses `select_from<Employee, "e1">` to create the first table alias `e1` (for employees) and `left_join<Employee, "e2">` to create the second alias `e2` (for managers)

2. **LEFT JOIN**: The `left_join` ensures that employees without managers (top-level employees with null `manager_id`) are still included in the results with a null manager name

3. **Column Selection**: 
   - `"name"_e1 | as<"employee">` - selects the employee's name from table e1
   - `"name"_e2 | as<"manager">` - selects the manager's name from table e2

4. **Join Condition**: `"manager_id"_e1 == "emp_id"_e2` implements the self-join condition matching employee's manager_id to manager's emp_id

5. **Database Connection**: Connects to "test_db.sqlite" and executes the query, returning the results as a vector of `EmployeeManager` structs

The function follows the sqlgen library's fluent API pattern, using compile-time string literals and pipe operators to build type-safe SQL queries.

