 * @return vector<CategoryReport>
 */
std::vector<CategoryReport> query_product_sales_report() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  if (!conn) {
    // Return empty vector if connection fails
    return {};
  }

  // Build the query using sqlgen's type-safe interface
  // Join Product and Sale tables, aggregate by category, and filter results
  const auto query =
      select_from<Product, "p">(
          "category"_p | as<"category">,
          sum("quantity"_s).as<"total_qty">(),
          sum("amount"_s).as<"total_amt">()
      ) |
      inner_join<Sale, "s">("product_id"_p == "product_id"_s) |
      group_by("category"_p) |
      to<std::vector<CategoryReport>>;

  // Execute the query
  auto result = query(conn);

  if (!result) {
    // Return empty vector if query fails
    return {};
  }

  // Get all results
  auto reports = result.value();

  // Filter categories with total_amt > 5000 (HAVING clause equivalent)
  std::vector<CategoryReport> filtered_reports;
  for (const auto& report : reports) {
    if (report.total_amt > 5000.0) {
      filtered_reports.push_back(report);
    }
  }

  return filtered_reports;
}

}  // namespace query_product_sales_report
