    22→    if constexpr (transpilation::has_reflection_method<Type>) {
    23→      return Parser<std::remove_cvref_t<typename Type::ReflectionType>>::read(
    24→                 _str)
    25→          .transform([](auto&& _t) { return Type(std::move(_t)); });
    26→
    27→    } else {
    28→      if (!_str) {
    29→        return error("NULL value encounted: Numeric value cannot be NULL.");
    30→      }
    31→
    32→      try {
    33→        if constexpr (std::is_floating_point_v<Type>) {
    34→          return static_cast<Type>(std::stod(*_str));
    35→        } else if constexpr (std::is_integral_v<Type>) {
    36→          return static_cast<Type>(std::stoll(*_str));
    37→        } else if constexpr (std::is_same_v<Type, bool>) {
    38→          return std::stoi(*_str) != 0;
    39→        } else if constexpr (std::is_enum_v<Type>) {
    40→          if (auto res = rfl::string_to_enum<Type>(*_str)) {
    41→            return Type{*res};
    42→          } else {
    43→            return error(res.error());
    44→          }
    45→        } else {
    46→          static_assert(rfl::always_false_v<Type>, "Unsupported type");
    47→        }
    48→
    49→      } catch (std::exception& e) {
