    56→    if constexpr (transpilation::has_reflection_method<Type>) {
    57→      return Parser<std::remove_cvref_t<typename Type::ReflectionType>>::write(
    58→          _t.reflection());
    59→    } else if constexpr (std::is_enum_v<Type>) {
    60→      return rfl::enum_to_string(_t);
    61→    } else {
    62→      return std::to_string(_t);
    63→    }
    64→  }
    65→
    66→  static dynamic::Type to_type() noexcept {
    67→    if constexpr (transpilation::has_reflection_method<Type>) {
    68→      return Parser<
    69→          std::remove_cvref_t<typename Type::ReflectionType>>::to_type();
    70→
    71→    } else if constexpr (std::is_same_v<T, bool>) {
    72→      return dynamic::types::Boolean{};
    73→
    74→    } else if constexpr (std::is_integral_v<T> && std::is_signed_v<T>) {
