   121→      constexpr auto values = rfl::get_enumerator_array<T>();
   122→      std::array<std::string_view, std::size(values)> enum_names{};
   123→      for (std::size_t i = 0; i < std::size(values); ++i) {
   124→        enum_names[i] = values[i].first;
