    44→          class... ColTypes>
    45→struct CreateIndex {
    46→  auto operator()(const auto& _conn) const {
    47→    return create_index_impl<
    48→        ValueType,
    49→        transpilation::columns_t<ValueType, typename ColTypes::ColType...>,
    50→        WhereType>(_conn, _name.str(), unique_, if_not_exists_, where_);
    51→  }
