#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace schema_migration_add_column {

struct User {
  PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  PrimaryKey<int, auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");

  // Check if connection succeeded
  if (conn_result.error()) {
    return false;
  }

  auto conn = std::move(conn_result).value();

  // Try to add phone_number column (VARCHAR(20))
  auto result1 = conn->execute("ALTER TABLE User ADD COLUMN phone_number VARCHAR(20);");

  // Check for errors - if column already exists, it will fail with an error message
  // SQLite returns "duplicate column name" error if column exists
  // We'll treat this as acceptable (idempotent migration)
  if (result1.error()) {
    auto error_msg = result1.error().value().what();
    // Check if it's a "duplicate column" error - if so, continue
    // Otherwise, return false
    if (std::string(error_msg).find("duplicate column") == std::string::npos) {
      // It's a different error, migration failed
      return false;
    }
    // Column already exists, that's okay - continue with next column
  }

  // Try to add is_active column (INTEGER with DEFAULT 1, representing boolean true)
  auto result2 = conn->execute("ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1;");

  // Check for errors - handle duplicate column case
  if (result2.error()) {
    auto error_msg = result2.error().value().what();
    // Check if it's a "duplicate column" error - if so, continue
    if (std::string(error_msg).find("duplicate column") == std::string::npos) {
      // It's a different error, migration failed
      return false;
    }
    // Column already exists, that's okay
  }

  // Migration succeeded
  return true;
}

} // namespace schema_migration_add_column
```

