struct Document {
  PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    // Return true if no IDs to delete
    if (ids.empty()) {
        return true;
    }

    // Connect to SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn_result) {
        return false;
    }

    auto conn = conn_result.value();

    // Get current timestamp
    auto now = std::chrono::system_clock::now();
    auto time_t_now = std::chrono::system_clock::to_time_t(now);
    std::tm tm_now;

#ifdef _WIN32
    localtime_s(&tm_now, &time_t_now);
#else
    localtime_r(&time_t_now, &tm_now);
#endif

    // Format timestamp as YYYY-MM-DD HH:MM:SS
    std::ostringstream oss;
    oss << std::put_time(&tm_now, "%Y-%m-%d %H:%M:%S");
    std::string current_timestamp = oss.str();

    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Build and execute update query with IN clause
    // UPDATE Document SET is_deleted = 1, deleted_at = CURRENT_TIMESTAMP WHERE doc_id IN (...)
    const auto update_query =
        update<Document>(
            "is_deleted"_c.set(1),
            "deleted_at"_c.set(current_timestamp)
        ) | where("doc_id"_c.in(ids));

    // Execute the update in a transaction
    auto result = begin_transaction(conn)
        .and_then(update_query)
        .and_then(commit);

    return result.has_value();
}

}  // namespace soft_delete_records

