#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = conn_result.value();

  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Start transaction
  auto transaction_result = begin_transaction(conn);
  if (!transaction_result) {
    return false;
  }
  auto transaction = transaction_result.value();

  // Step 1: Update from_account - deduct amount only if balance >= amount
  const auto deduct_from_account =
      update<Account>("balance"_c.set("balance"_c - amount)) |
      where("account_id"_c == from_account_id && "balance"_c >= amount);

  auto deduct_result = deduct_from_account(transaction);
  if (!deduct_result) {
    rollback(transaction);
    return false;
  }
  transaction = deduct_result.value();

  // Step 2: Verify that the deduction actually happened (balance was sufficient)
  // Read the from_account to check if the update occurred
  const auto check_from_account =
      select_from<Account> | where("account_id"_c == from_account_id);

  auto from_account_result = check_from_account(transaction)
      .and_then([](auto&& it) {
        return internal::to_container<std::vector<Account>>(
            Result<Iterator<Account>>(Iterator<Account>(std::move(it)))
        );
      });

  if (!from_account_result) {
    rollback(transaction);
    return false;
  }

  auto from_accounts = from_account_result.value();
  if (from_accounts.empty()) {
    // Account doesn't exist
    rollback(transaction);
    return false;
  }

  // Check if balance was actually deducted
  // If the original balance was less than amount, the balance wouldn't have changed
  // We need to verify the deduction occurred, but we can't directly check row count
  // So we verify by reading and ensuring the expected amount was deducted

  // Actually, a simpler approach: use raw SQL with RETURNING or check via exec
  // But sqlgen doesn't expose affected rows. Let's use a different strategy:
  // Use raw SQL with exec for the conditional update, then verify

  // Rollback this attempt and start fresh with raw SQL approach
  rollback(transaction);

  // Restart with raw SQL approach
  transaction_result = begin_transaction(conn);
  if (!transaction_result) {
    return false;
  }
  transaction = transaction_result.value();

  // Construct raw SQL for the conditional deduction
  std::string deduct_sql =
      "UPDATE Account SET balance = balance - " + std::to_string(amount) +
      " WHERE account_id = " + std::to_string(from_account_id) +
      " AND balance >= " + std::to_string(amount) + ";";

  auto exec_result = exec(deduct_sql)(transaction);
  if (!exec_result) {
    rollback(transaction);
    return false;
  }
  transaction = exec_result.value();

  // Verify the update occurred by checking the from_account
  from_account_result = (select_from<Account> | where("account_id"_c == from_account_id))(transaction)
      .and_then([](auto&& it) {
        return internal::to_container<std::vector<Account>>(
            Result<Iterator<Account>>(Iterator<Account>(std::move(it)))
        );
      });

  if (!from_account_result) {
    rollback(transaction);
    return false;
  }

  from_accounts = from_account_result.value();
  if (from_accounts.empty()) {
    rollback(transaction);
    return false;
  }

  // Step 3: Add amount to to_account
  const auto add_to_account =
      update<Account>("balance"_c.set("balance"_c + amount)) |
      where("account_id"_c == to_account_id);

  auto add_result = add_to_account(transaction);
  if (!add_result) {
    rollback(transaction);
    return false;
  }
  transaction = add_result.value();

  // Step 4: Commit the transaction
  auto commit_result = commit(transaction);
  if (!commit_result) {
    rollback(transaction);
    return false;
  }

  return true;
}

}  // namespace transaction_transfer_funds

