    12→namespace sqlgen::sqlite {
    13→
    14→Result<Nothing> Connection::actual_insert(
    15→    const std::vector<std::vector<std::optional<std::string>>>& _data,
    16→    sqlite3_stmt* _stmt) const noexcept {
    17→  for (const auto& row : _data) {
    18→    const auto num_cols = static_cast<int>(row.size());
    19→
    20→    for (int i = 0; i < num_cols; ++i) {
    21→      if (row[i]) {
    22→        const auto res =
    23→            sqlite3_bind_text(_stmt, i + 1, row[i]->c_str(),
    24→                              static_cast<int>(row[i]->size()), SQLITE_STATIC);
    25→        if (res != SQLITE_OK) {
    26→          return error(sqlite3_errmsg(conn_.get()));
    27→        }
    28→      } else {
    29→        const auto res = sqlite3_bind_null(_stmt, i + 1);
    30→        if (res != SQLITE_OK) {
    31→          return error(sqlite3_errmsg(conn_.get()));
    32→        }
    33→      }
    34→    }
    35→
    36→    auto res = sqlite3_step(_stmt);
    37→    if (res != SQLITE_OK && res != SQLITE_ROW && res != SQLITE_DONE) {
    38→      return error(sqlite3_errmsg(conn_.get()));
    39→    }
    40→
    41→    res = sqlite3_reset(_stmt);
    42→    if (res != SQLITE_OK) {
    43→      return error(sqlite3_errmsg(conn_.get()));
    44→    }
    45→  }
    46→
    47→  const auto res = sqlite3_clear_bindings(_stmt);
    48→  if (res != SQLITE_OK) {
    49→    return error(sqlite3_errmsg(conn_.get()));
    50→  }
    51→
    52→  return Nothing{};
    53→}
    54→
    55→Result<Nothing> Connection::begin_transaction() noexcept {
    56→  return execute("BEGIN TRANSACTION;");
    57→}
    58→
    59→Result<Nothing> Connection::commit() noexcept { return execute("COMMIT;"); }
    60→
    61→rfl::Result<Ref<Connection>> Connection::make(
    62→    const std::string& _fname) noexcept {
    63→  try {
    64→    return Ref<Connection>::make(_fname);
    65→  } catch (std::exception& e) {
    66→    return error(e.what());
    67→  }
    68→}
    69→
    70→Result<Nothing> Connection::execute(const std::string& _sql) noexcept {
    71→  char* errmsg = nullptr;
    72→  sqlite3_exec(conn_.get(), _sql.c_str(), nullptr, nullptr, &errmsg);
    73→  if (errmsg) {
    74→    const auto err = error("Executing '" + _sql + "' failed: " + errmsg);
    75→    sqlite3_free(errmsg);
    76→    return err;
    77→  }
    78→  return Nothing{};
    79→}
    80→
    81→Result<Nothing> Connection::insert_impl(
    82→    const dynamic::Insert& _stmt,
    83→    const std::vector<std::vector<std::optional<std::string>>>&
    84→        _data) noexcept {
    85→  const auto sql = to_sql_impl(_stmt);
    86→  return prepare_statement(sql).and_then(
    87→      [&](auto _p_stmt) { return actual_insert(_data, _p_stmt.get()); });
    88→}
    89→
    90→typename Connection::ConnPtr Connection::make_conn(const std::string& _fname) {
    91→  sqlite3* conn = nullptr;
    92→  const auto err = sqlite3_open(_fname.c_str(), &conn);
    93→  if (err) {
    94→    throw std::runtime_error("Can't open database: " +
    95→                             std::string(sqlite3_errmsg(conn)));
    96→  }
    97→  return ConnPtr::make(std::shared_ptr<sqlite3>(conn, &sqlite3_close)).value();
    98→}
    99→
   100→Result<Ref<IteratorBase>> Connection::read_impl(
   101→    const dynamic::SelectFrom& _query) {
   102→  const auto sql = to_sql_impl(_query);
   103→
   104→  sqlite3_stmt* p_stmt = nullptr;
   105→
   106→  sqlite3_prepare(conn_.get(), /* Database handle */
   107→                  sql.c_str(), /* SQL statement, UTF-8 encoded */
   108→                  sql.size(),  /* Maximum length of zSql in bytes. */
   109→                  &p_stmt,     /* OUT: Statement handle */
   110→                  nullptr      /* OUT: Pointer to unused portion of zSql */
   111→  );
   112→
   113→  if (!p_stmt) {
   114→    return error(sqlite3_errmsg(conn_.get()));
   115→  }
   116→
   117→  return Ref<sqlite3_stmt>::make(StmtPtr(p_stmt, &sqlite3_finalize))
   118→      .transform([&](auto _stmt) -> Ref<IteratorBase> {
   119→        return Ref<Iterator>::make(_stmt, conn_);
   120→      });
   121→}
   122→
   123→Result<Connection::StmtPtr> Connection::prepare_statement(
   124→    const std::string& _sql) const noexcept {
   125→  sqlite3_stmt* p_stmt = nullptr;
   126→
   127→  sqlite3_prepare(conn_.get(),  /* Database handle */
   128→                  _sql.c_str(), /* SQL statement, UTF-8 encoded */
   129→                  _sql.size(),  /* Maximum length of zSql in bytes. */
   130→                  &p_stmt,      /* OUT: Statement handle */
   131→                  nullptr       /* OUT: Pointer to unused portion of zSql */
   132→  );
   133→
   134→  if (!p_stmt) {
   135→    return error("Preparing the following statement failed: " + _sql +
   136→                 " Reason: " + sqlite3_errmsg(conn_.get()));
   137→  }
   138→
   139→  return StmtPtr(p_stmt, &sqlite3_finalize);
   140→}
   141→
   142→Result<Nothing> Connection::rollback() noexcept { return execute("ROLLBACK;"); }
   143→
   144→Result<Nothing> Connection::start_write(const dynamic::Write& _stmt) {
   145→  if (stmt_) {
   146→    return error(
   147→        "A write operation has already been launched. You need to call "
   148→        ".end_write() before you can start another.");
   149→  }
   150→
   151→  const auto sql = to_sql_impl(_stmt);
   152→
   153→  return prepare_statement(sql)
   154→      .transform([&](auto&& _stmt) {
   155→        stmt_ = std::move(_stmt);
   156→        return Nothing{};
   157→      })
   158→      .and_then([&](const auto&) { return begin_transaction(); });
   159→}
   160→
   161→Result<Nothing> Connection::write_impl(
