// eas_common.hpp
#pragma once



struct Student {
  PrimaryKey<Varchar<10>> SNo;
  Varchar<30> SName;
  int Sex = 1;
  std::optional<DateTime> Birthday;
  std::optional<uint32_t> Major;
  std::optional<double> Scorses = 0.0;
  std::optional<std::string> Remark;
};

struct Course {
  PrimaryKey<uint32_t, auto_incr> CID;
  Varchar<50> CName;
  std::optional<int> Term = 1;
  std::optional<int> CTime;
  int Credit = 0;
};

struct Score {
  PrimaryKey<uint32_t, auto_incr> ScID;
  ForeignKey<Varchar<10>, Student, "SNo"> SNo;
  ForeignKey<uint32_t, Course, "CID"> CID;
  std::optional<double> Score;
};

struct Major {
  PrimaryKey<uint32_t> MID;
  Varchar<30> MName;
};

const std::string db_path = "data/eas_database.db";

void design_eas_database_without_major() {
  std::filesystem::create_directories("data");
  sqlite::connect(db_path)
      .and_then([](auto&& conn) {
        return exec(conn, "PRAGMA foreign_keys = ON;");
      })
      .and_then(create_table<Student> | if_not_exists)
      .and_then(create_table<Course> | if_not_exists)
      .and_then(create_table<Score> | if_not_exists)
      .value();
}

void design_eas_database_with_major() {
  design_eas_database_without_major();

  sqlite::connect(db_path)
      .and_then(create_table<Major> | if_not_exists)
      .value();
}

