// eas_common.hpp
#pragma once

struct Student {
  PrimaryKey<Varchar<10>> SNo;
  Varchar<30> SName;
  int Sex = 1;
  std::optional<DateTime> Birthday;
  std::optional<uint32_t> Major;
  std::optional<double> Scorses = 0.0;
  std::optional<std::string> Remark;
};

struct Course {
  PrimaryKey<uint32_t, auto_incr> CID;
  Varchar<50> CName;
  std::optional<int> Term = 1;
  std::optional<int> CTime;
  int Credit = 0;
};

struct Score {
  PrimaryKey<uint32_t, auto_incr> ScID;
  ForeignKey<Varchar<10>, Student, "SNo"> SNo;
  ForeignKey<uint32_t, Course, "CID"> CID;
  std::optional<double> Score;
};

struct Major {
  PrimaryKey<uint32_t> MID;
  Varchar<30> MName;
};

const std::string db_path = "data/eas_database.db";

void design_eas_database_without_major() {
  std::filesystem::create_directories("data");
  sqlite::connect(db_path)
      .and_then([](auto&& conn) {
        return exec(conn, "PRAGMA foreign_keys = ON;");
      })
      .and_then(create_table<Student> | if_not_exists)
      .and_then(create_table<Course> | if_not_exists)
      .and_then(create_table<Score> | if_not_exists)
      .value();
}

void design_eas_database_with_major() {
  design_eas_database_without_major();

  sqlite::connect(db_path)
      .and_then(create_table<Major> | if_not_exists)
      .value();
}

// update_eas_table.hpp
#pragma once

namespace update_eas_table {

void update_eas_table() {
  design_eas_database_with_major();

  sqlite::connect(db_path)
      .and_then([](auto&& conn) {
        // 1. Add Grade column to Score table (CHAR(1) NOT NULL)
        return exec(conn, "ALTER TABLE Score ADD COLUMN Grade CHAR(1) NOT NULL DEFAULT 'F';");
      })
      .and_then([](auto&& conn) {
        // 2. Modify Age column in Student table to INT NULL
        // Note: SQLite has limited ALTER TABLE support. To change column type,
        // we need to recreate the table. Here's a workaround:
        return exec(conn, R"(
          CREATE TABLE Student_new (
            SNo VARCHAR(10) PRIMARY KEY,
            SName VARCHAR(30),
            Sex INTEGER DEFAULT 1,
            Birthday DATETIME,
            Major INTEGER,
            Scorses REAL DEFAULT 0.0,
            Remark TEXT,
            Age INTEGER NULL
          );
        )");
      })
      .and_then([](auto&& conn) {
        return exec(conn, R"(
          INSERT INTO Student_new (SNo, SName, Sex, Birthday, Major, Scorses, Remark, Age)
          SELECT SNo, SName, Sex, Birthday, Major, Scorses, Remark, 
                 CAST(Age AS INTEGER) FROM Student;
        )");
      })
      .and_then([](auto&& conn) {
        return exec(conn, "DROP TABLE Student;");
      })
      .and_then([](auto&& conn) {
        return exec(conn, "ALTER TABLE Student_new RENAME TO Student;");
      })
      .and_then([](auto&& conn) {
        // 3. Drop Major table
        return exec(conn, "DROP TABLE Major;");
      })
      .value();
}

} // namespace update_eas_table
```

**Key implementation notes:**

1. **Add Grade column**: Uses `ALTER TABLE ... ADD COLUMN` with `DEFAULT 'F'` to handle existing rows (since NOT NULL requires a default value for existing data).

2. **Modify Age column type**: SQLite doesn't support direct column type modification, so I implemented the standard SQLite workaround:
   - Create a new table with the correct schema
   - Copy data from old table (with CAST to convert Age to INT)
   - Drop the old table
   - Rename the new table

3. **Drop Major table**: Simple `DROP TABLE` statement.

The function chains all operations using the monadic `.and_then()` pattern that the library uses, ensuring operations execute sequentially and handling errors through the monadic interface.

