namespace update_order_status {

struct Order {
  PrimaryKey<int> order_id;
  std::string status;
  DateTime order_date;
  double total_amount;
};

/**
 * @brief Update the status of orders based on specific criteria.
 * @return true If the update is successful, false otherwise.
 */
bool update_order_status() {
  // Connect to the SQLite database
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Use the literals namespace for column references
  using namespace sqlgen::literals;

  // Create the update query:
  // UPDATE "Order" SET status = 'expired'
  // WHERE status = 'pending' AND order_date < '2024-01-01'
  const auto query = update<Order>("status"_c.set("expired")) |
                     where("status"_c == "pending" &&
                           "order_date"_c < DateTime("2024-01-01 00:00:00"));

  // Execute the query and check the result
  const auto result = query(conn);

  // Return true if successful, false otherwise
  return result.has_value();
}

} // namespace update_order_status

