Here's the complete implementation:

```cpp
#pragma once

#include <vector>
#include <string>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace schema_create_view_sales_summary {

using namespace sqlgen;
using namespace sqlgen::literals;

struct Product {
  PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  PrimaryKey<int, auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * @return A vector of SalesSummary structs
 */
std::vector<SalesSummary> create_view_sales_summary() {
  // Define the query for the SalesSummary view
  const auto sales_summary_query =
      select_from<Sale, "s">(
          "name"_p | as<"product_name">,
          sum("quantity"_s) | as<"total_quantity">,
          sum("amount"_s) | as<"total_revenue">) |
      inner_join<Product, "p">("product_id"_s == "product_id"_p) |
      group_by("name"_p);

  // Create the view and read the results
  const auto create_and_read_view =
      create_as<SalesSummary>(sales_summary_query) | if_not_exists;

  // Connect to database, create view, and read the results
  auto result = sqlite::connect("test_db.sqlite")
                    .and_then(create_and_read_view)
                    .and_then(sqlgen::read<std::vector<SalesSummary>>)
                    .value();

  return result;
}

}  // namespace schema_create_view_sales_summary
```

