std::string generate_sql_dry_run() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Build a complex query with:
  // 1. Join between tables A and B on A.id = B.a_id
  // 2. Where clause: score > 10 AND name LIKE '%x%'
  // 3. Order by score descending
  // 4. Limit to 10 results
  const auto query =
      select_from<A, "a">(
          "id"_a | as<"a_id">,
          "name"_a | as<"name">,
          "id"_b | as<"b_id">,
          "score"_b | as<"score">
      ) |
      inner_join<B, "b">("id"_a == "a_id"_b) |
      where("score"_b > 10.0 and "name"_a.like("%x%")) |
