#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace upsert_inventory_items {

struct Inventory {
  sqlgen::PrimaryKey<int> item_id;
  std::string name;
  int quantity;
};

/**
 * This function demonstrates how to use upsert (insert or replace) statements in write API.
 * It inserts or replaces the given inventory items in the Inventory table.
 * Returns: true if the item is inserted, false if the item is already in the table.
 */
bool upsert_inventory_items(Inventory item) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = conn_result.value();

  // Create the Inventory table if it doesn't exist
  auto create_result = (create_table<Inventory> | if_not_exists)(conn);
  if (!create_result) {
    return false;
  }

  // Check if the item already exists by querying with the primary key
  auto existing_item_result = (read<std::vector<Inventory>> |
                                where("item_id"_c == item.item_id.value()))(conn);

  bool item_exists = false;
  if (existing_item_result) {
    auto existing_items = existing_item_result.value();
    item_exists = !existing_items.empty();
  }

  // Perform insert or replace operation
  auto upsert_result = insert_or_replace(conn, item);
  if (!upsert_result) {
    return false;
  }

  // Return true if item was inserted (didn't exist), false if replaced (existed)
  return !item_exists;
}

}  // namespace upsert_inventory_items

