#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_social_network {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze who and whom are friends in the social network.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the SQLite database
    const auto conn = sqlite::connect("test_db.sqlite");

    // Build the query to join Friendship with User tables twice
    // to get the names of both friends
    const auto get_friends = 
        select_from<Friendship, "f">(
            "username"_u1 | as<"user1_name">,
            "username"_u2 | as<"user2_name">
        ) |
        inner_join<User, "u1">("user1_id"_f == "user_id"_u1) |
        inner_join<User, "u2">("user2_id"_f == "user_id"_u2) |
        to<std::vector<FriendConnection>>;

    // Execute the query and return the result
    return get_friends(conn).value();
}

}  // namespace analyze_social_network
```

This implementation:

1. **Uses the sqlgen library** for type-safe SQL operations with SQLite
2. **Connects to "test_db.sqlite"** database
3. **Performs INNER JOINs** between the `Friendship` table and the `User` table twice:
   - First join (`u1`) to get the username of the first user (`user1_id`)
   - Second join (`u2`) to get the username of the second user (`user2_id`)
4. **Selects the usernames** and aliases them as `user1_name` and `user2_name`
5. **Returns a vector of `FriendConnection`** structs containing the friend pairs

The generated SQL query would be equivalent to:
```sql
SELECT u1."username" AS "user1_name", u2."username" AS "user2_name"
FROM "Friendship" f
INNER JOIN "User" u1 ON f."user1_id" = u1."user_id"
INNER JOIN "User" u2 ON f."user2_id" = u2."user_id"
```

