```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace join_orders_customers_payments {

struct Customer {
  PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  PrimaryKey<int> order_id;
  int customer_id;
  Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct Payment {
  PrimaryKey<int> payment_id;
  int order_id;
  double amount;
};

struct Consolidated {
  PrimaryKey<int> order_id;
  std::string customer_name;
  double amount;
};

/**
 * This function demonstrates how to join three tables (Orders, Customers, and Payments)
 * and return a consolidated view with order_id, customer_name, and amount.
 * It orders the results by amount in descending order.
 * Returns: std::vector<Consolidated>.
 */
std::vector<Consolidated> join_orders_customers_payments() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Build the query: join Orders, Customers, and Payments
  const auto query =
      select_from<Order, "t1">(
          "order_id"_t1 | as<"order_id">,
          "name"_t2 | as<"customer_name">,
          "amount"_t3 | as<"amount">
      ) |
      inner_join<Customer, "t2">("customer_id"_t1 == "customer_id"_t2) |
      inner_join<Payment, "t3">("order_id"_t1 == "order_id"_t3) |
      order_by(desc("amount"_t3)) |
      to<std::vector<Consolidated>>;

  // Connect to the database and execute the query
  return sqlite::connect("test_db.sqlite")
      .and_then(query)
      .value();
}

}  // namespace join_orders_customers_payments
```

**Key points of the implementation:**

1. **Includes**: Added the necessary headers (`sqlgen.hpp` and `sqlgen/sqlite.hpp`)

2. **Using directives**: Used `sqlgen` and `sqlgen::literals` namespaces for cleaner syntax

3. **Query construction**:
   - Start with `select_from<Order, "t1">` selecting from the Orders table with alias "t1"
   - Select three columns: `order_id` from Orders, `name` from Customers, and `amount` from Payments
   - Use `inner_join<Customer, "t2">` to join Customers table on `customer_id`
   - Use `inner_join<Payment, "t3">` to join Payments table on `order_id`
   - Use `order_by(desc("amount"_t3))` to order by payment amount in descending order
   - Use `to<std::vector<Consolidated>>` to specify the return type

4. **Database connection**: 
   - Connect to "test_db.sqlite" using `sqlite::connect("test_db.sqlite")`
   - Chain the query execution with `.and_then(query)`
   - Extract the result with `.value()`

5. **Table aliases**: Used `_t1`, `_t2`, `_t3` suffixes from the `sqlgen::literals` namespace to reference columns from different tables

This implementation follows the sqlgen library patterns and will generate SQL similar to:
```sql
SELECT t1."order_id" AS "order_id", t2."name" AS "customer_name", t3."amount" AS "amount"
FROM "Order" t1
INNER JOIN "Customer" t2 ON t1."customer_id" = t2."customer_id"
INNER JOIN "Payment" t3 ON t1."order_id" = t3."order_id"
ORDER BY t3."amount" DESC
```

