#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

using namespace sqlgen;

namespace cascade_delete_demo {

struct Parent {
  PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  PrimaryKey<int> child_id;
  ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * @param parent_id The ID of the parent record to delete.
 * Returns: true if the cascade delete worked as expected, false otherwise.
 */
bool cascade_delete_demo(int parent_id) {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = conn_result.value();

  // Enable foreign key constraints in SQLite (required for cascade delete)
  auto fk_enable = exec(conn, "PRAGMA foreign_keys = ON");
  if (!fk_enable) {
    return false;
  }

  // Drop existing tables if they exist
  auto drop_child = (drop<Child> | if_exists)(conn);
  if (!drop_child) {
    return false;
  }

  auto drop_parent = (drop<Parent> | if_exists)(conn);
  if (!drop_parent) {
    return false;
  }

  // Create Parent table
  auto create_parent = create_table<Parent>(conn);
  if (!create_parent) {
    return false;
  }

  // Create Child table with foreign key constraint
  // Note: SQLite automatically adds ON DELETE CASCADE when ForeignKey is used
  auto create_child = create_table<Child>(conn);
  if (!create_child) {
    return false;
  }

  // Insert parent record
  std::vector<Parent> parents = {
      Parent{.parent_id = parent_id, .name = "Parent Record"}
  };

  auto insert_parent = insert(std::ref(parents))(conn);
  if (!insert_parent) {
    return false;
  }

  // Insert child records with the same parent_id
  std::vector<Child> children = {
      Child{.child_id = 1, .parent_id = parent_id, .note = "Child 1"},
      Child{.child_id = 2, .parent_id = parent_id, .note = "Child 2"},
      Child{.child_id = 3, .parent_id = parent_id, .note = "Child 3"}
  };

  auto insert_children = insert(std::ref(children))(conn);
  if (!insert_children) {
    return false;
  }

  // Verify children were inserted
  auto children_before = read<std::vector<Child>>(conn);
  if (!children_before) {
    return false;
  }

  size_t child_count_before = children_before.value().size();
  if (child_count_before != 3) {
    return false;  // Expected 3 children
  }

  // Delete the parent record
  auto delete_query = delete_from<Parent> | where("parent_id"_c == parent_id);
  auto delete_result = delete_query(conn);
  if (!delete_result) {
    return false;
  }

  // Verify that child rows were automatically deleted (cascade delete)
  auto children_after = read<std::vector<Child>>(conn);
  if (!children_after) {
    return false;
  }

  size_t child_count_after = children_after.value().size();

  // Clean up - drop tables
  drop<Child> | if_exists(conn);
  drop<Parent> | if_exists(conn);

  // Return true if all children were deleted (cascade worked)
  return child_count_after == 0;
}

}  // namespace cascade_delete_demo

