namespace column_is_null_checks {

template <typename T>
using PrimaryKey = sqlgen::PrimaryKey<T>;

struct Profile {
  PrimaryKey<int> profile_id;
  std::string display_name;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

struct Result {
  int profile_id;
  std::string display_name;
};

std::vector<Result> column_is_null_checks() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return {};
  }

  // Query to filter records with missing bio OR avatar_url
  // Using IS NULL to find records where either field is missing
  auto results = conn.and_then(
      select_from<Profile>("profile_id"_c, "display_name"_c) |
      where("bio"_c.is_null() or "avatar_url"_c.is_null()) |
      to<std::vector<Result>>
  );

  if (!results) {
    return {};
  }

  return results.value();
}

}  // namespace column_is_null_checks

