#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * sets the balance and status of an Account identified by acc_id.
 * @param acc_id: The id of Account to be updated.
 * @returns true if the update operations are successful, and false otherwise.
 */
bool update_set_operations(int acc_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = conn_result.value();

  // Create the Account table
  auto create_result = (create_table<Account> | if_not_exists)(conn);
  if (!create_result) {
    return false;
  }

  // Insert initial test data
  std::vector<Account> accounts = {
    Account{.account_id = 1, .balance = 1000.0, .status = "active"},
    Account{.account_id = 2, .balance = 2000.0, .status = "active"},
    Account{.account_id = 3, .balance = 3000.0, .status = "inactive"}
  };

  auto write_result = write(conn, accounts);
  if (!write_result) {
    return false;
  }

  // Update the balance to 5000.0 and status to "premium" for the account with acc_id
  auto update_query = update<Account>(
    "balance"_c.set(5000.0),
    "status"_c.set("premium")
  ) | where("account_id"_c == acc_id);

  auto update_result = update_query(conn);
  if (!update_result) {
    return false;
  }

  // Verify the changes persisted
  auto read_result = read<std::vector<Account>>(conn);
  if (!read_result) {
    return false;
  }

  auto updated_accounts = read_result.value();

  // Check if the account with acc_id has been updated correctly
  for (const auto& account : updated_accounts) {
    if (account.account_id.get() == acc_id) {
      if (account.balance == 5000.0 && account.status == "premium") {
        return true;
      }
      return false;
    }
  }

  // If account with acc_id wasn't found, return false
  return false;
}

}  // namespace update_set_operations
```

This implementation:

1. **Creates the Account table** - Uses `create_table<Account>` with `if_not_exists` to ensure the table exists
2. **Inserts test data** - Adds 3 sample accounts to the database using `write()`
3. **Updates using set()** - Uses `update<Account>()` with two `set()` calls to update both `balance` and `status` columns for the account matching `acc_id`
4. **Verifies changes persisted** - Reads back all accounts and checks that the specified account has the correct updated values (balance = 5000.0, status = "premium")

The function returns `true` if all operations succeed and the verification confirms the updates were persisted correctly, and `false` otherwise.

