    auto conn = sqlite::connect("test_db.sqlite");

    // Build the query using CONCAT to combine first_name and last_name with a space
    auto query = select_from<Person>(
        concat("first_name"_c, " ", "last_name"_c) | as<"full_name">
    ) | to<std::vector<FullName>>;

    // Execute the query and return the result
    return conn.and_then(query).value();
