#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * @param limit_count The number of top products to retrieve. Default is 10.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite").value();

  // Build the query to get top products by total sales
  const auto query =
      select_from<Product, "p">(
          "product_id"_p | as<"product_id">,
          "product_name"_p | as<"product_name">,
          "category"_p | as<"category">,
          sum("price"_p * "quantity"_s) | as<"total_sales">) |
      inner_join<Sales, "s">("product_id"_p == "product_id"_s) |
      group_by("product_id"_p, "product_name"_p, "category"_p) |
      order_by(desc(sum("price"_p * "quantity"_s))) |
      limit(limit_count) |
      to<std::vector<TopProduct>>;

  // Execute the query and return the results
  return query(conn).value();
}

}  // namespace get_top_products

