     6→
     7→namespace sqlgen {
     8→
     9→template <class _ConnType>
    10→  requires is_connection<_ConnType>
    11→class Transaction {
    12→ public:
    13→  using ConnType = _ConnType;
    14→
    15→  Transaction(const Ref<ConnType>& _conn)
    16→      : conn_(_conn), transaction_ended_(false) {}
    17→
    18→  Transaction(const Transaction& _other) = delete;
    19→
    20→  Transaction(Transaction&& _other) noexcept
    21→      : conn_(std::move(_other.conn_)),
    22→        transaction_ended_(_other.transaction_ended_) {
    23→    _other.transaction_ended_ = true;
    24→  }
    25→
    26→  ~Transaction() {
    27→    if (!transaction_ended_) {
    28→      rollback();
    29→    }
    30→  }
    31→
    32→  Result<Nothing> begin_transaction() {
    33→    if (!transaction_ended_) {
    34→      return error("Transaction has already begun, cannot begin another.");
    35→    }
    36→    return conn_->begin_transaction().transform([&](const auto& _nothing) {
    37→      transaction_ended_ = false;
    38→      return _nothing;
    39→    });
    40→  }
    41→
    42→  Result<Nothing> commit() {
    43→    if (transaction_ended_) {
    44→      return error("Transaction has already ended, cannot commit.");
    45→    }
    46→    return conn_->commit().transform([&](const auto& _nothing) {
    47→      transaction_ended_ = true;
    48→      return _nothing;
    49→    });
    50→  }
    51→
    52→  const Ref<ConnType>& conn() const noexcept { return conn_; }
    53→
    54→  Result<Nothing> execute(const std::string& _sql) {
    55→    return conn_->execute(_sql);
    56→  }
    57→
    58→  template <class ItBegin, class ItEnd>
    59→  Result<Nothing> insert(const dynamic::Insert& _stmt, ItBegin _begin,
    60→                         ItEnd _end) {
    61→    return conn_->insert(_stmt, _begin, _end);
    62→  }
    63→
    64→  Transaction& operator=(const Transaction& _other) = delete;
    65→
    66→  Transaction& operator=(Transaction&& _other) noexcept {
    67→    if (this == &_other) {
    68→      return *this;
    69→    }
    70→    conn_ = _other.conn_;
    71→    transaction_ended_ = _other.transaction_ended_;
    72→    _other.transaction_ended_ = true;
    73→    return *this;
    74→  }
    75→
    76→  template <class ContainerType>
    77→  Result<ContainerType> read(const dynamic::SelectFrom& _query) {
    78→    return conn_->template read<ContainerType>(_query);
    79→  }
    80→
    81→  Result<Nothing> rollback() noexcept {
    82→    if (transaction_ended_) {
    83→      return error("Transaction has already ended, cannot roll back.");
    84→    }
    85→    return conn_->rollback().transform([&](const auto& _nothing) {
    86→      transaction_ended_ = true;
    87→      return _nothing;
    88→    });
    89→  }
    90→
    91→  std::string to_sql(const dynamic::Statement& _stmt) noexcept {
    92→    return conn_->to_sql(_stmt);
    93→  }
    94→
    95→  Result<Nothing> start_write(const dynamic::Write& _stmt) {
    96→    return conn_->start_write(_stmt);
    97→  }
    98→
    99→  Result<Nothing> end_write() { return conn_->end_write(); }
   100→
   101→  template <class ItBegin, class ItEnd>
   102→  Result<Nothing> write(ItBegin _begin, ItEnd _end) {
   103→    return conn_->write(_begin, _end);
   104→  }
   105→
   106→ private:
   107→  Ref<ConnType> conn_;
   108→
   109→  bool transaction_ended_;
   110→};
   111→
   112→}  // namespace sqlgen
