#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace create_view_order_summary {

struct Order {
  static constexpr const char* tablename = "Order";
  PrimaryKey<int> order_id;
  std::string customer;
};

struct OrderItem {
  static constexpr const char* tablename = "OrderItem";
  PrimaryKey<int> item_id;
  int order_id;
  double unit_price;
  int quantity;
};

struct OrderSummary {
  static constexpr const char* tablename = "OrderSummaryView";
  static constexpr bool is_view = true;
  PrimaryKey<int> order_id;
  std::string customer;
  double total;
};

/**
 * Description: Create a view `OrderSummaryView` that shows order ID, customer name, and (unit_price * quantity) as total price for each order.
 * Returns: std::vector<OrderSummary>.
 */
std::vector<OrderSummary> create_view_order_summary() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Create the view query: SELECT o.order_id, o.customer, SUM(oi.unit_price*oi.quantity) as total
    // FROM Order o INNER JOIN OrderItem oi ON o.order_id=oi.order_id
    // GROUP BY o.order_id, o.customer
    const auto view_query = 
        select_from<Order, "o">(
            "order_id"_o | as<"order_id">,
            "customer"_o | as<"customer">,
            sum("unit_price"_oi * "quantity"_oi) | as<"total">
        ) | 
        inner_join<OrderItem, "oi">("order_id"_o == "order_id"_oi) |
        group_by("order_id"_o, "customer"_o);

    // Create the view
    const auto create_view = create_as<OrderSummary>(view_query) | if_not_exists;

    // Connect to the database, create the view, and read from it
    return sqlite::connect("test_db.sqlite")
        .and_then(create_view)
        .and_then(sqlgen::read<std::vector<OrderSummary>>)
        .value();
}

}  // namespace create_view_order_summary
```

This implementation:

1. **Defines the table structures** with proper `tablename` attributes matching the database tables ("Order" and "OrderItem")

2. **Creates the view query** using sqlgen's fluent API:
   - Uses `select_from<Order, "o">` to select from the Order table with alias "o"
   - Selects order_id and customer from the Order table
   - Uses `sum()` aggregation function on the product of unit_price and quantity
   - Uses `inner_join` to join Order and OrderItem tables on order_id
   - Uses `group_by` to group by order_id and customer

3. **Creates the view** using `create_as<OrderSummary>()` with `if_not_exists` modifier

4. **Connects to the database** "test_db.sqlite" using `sqlite::connect()`

5. **Chains operations** using `.and_then()`:
   - First creates the view
   - Then reads all records from the view into a `std::vector<OrderSummary>`

6. **Returns the results** by calling `.value()` on the result monad

The code follows the sqlgen library patterns demonstrated in the test files, using column literals (e.g., `"order_id"_o` for the "o" table alias), aggregation functions, joins, and the functional pipeline style with `and_then()`.

