std::vector<WeekdayStats> weekday_sales_analysis() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Create query to compute weekday and sum quantity, grouped by weekday
  const auto get_weekday_stats =
      select_from<Sales>(
          weekday("sale_date"_c) | as<"weekday">,
          sum("quantity"_c) | as<"total_quantity">()) |
      group_by(weekday("sale_date"_c)) |
      order_by("weekday"_c) |
      to<std::vector<WeekdayStats>>;

  // Connect to database and execute query
  const auto result = sqlite::connect("test_db.sqlite")
                          .and_then(get_weekday_stats)
                          .value();

  return result;
}

