namespace project_time_tracking {

using namespace sqlgen;
using namespace sqlgen::literals;

struct Project {
  PrimaryKey<int> project_id;
  std::string name;
};

struct TimeLog {
  PrimaryKey<int> log_id;
  int project_id;
  Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  Timestamp<"%Y-%m-%d %H:%M:%S"> end_time;
};

struct TimeMetrics {
  PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  // Connect to the SQLite database
  const auto conn = sqlite::connect("test_db.sqlite");

  // Build the query with inner join and temporal operations
  const auto get_time_metrics = 
      select_from<Project, "p">(
          "project_id"_p | as<"project_id">,
          "name"_p | as<"name">,
          day("start_time"_t) | as<"day">,
          month("start_time"_t) | as<"month">,
          year("start_time"_t) | as<"year">,
          hour("start_time"_t) | as<"hour">,
          minute("start_time"_t) | as<"minute">,
          second("start_time"_t) | as<"second">,
          days_between("start_time"_t, "end_time"_t) | as<"duration_days">
      ) |
      inner_join<TimeLog, "t">("project_id"_p == "project_id"_t) |
      to<std::vector<TimeMetrics>>;

  // Execute the query and return the result
  return conn.and_then(get_time_metrics).value();
}

}  // namespace project_time_tracking
