inline std::vector<Target> create_table_as_select() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite").value();

    // Create a query to select value from Source where value > 100
    const auto target_query = select_from<Source>("value"_c) | 
                              where("value"_c > 100);

    // Create table Target from the query
    const auto create_target = create_as<Target>(target_query) | if_not_exists;

    // Execute the create table statement and then read the results
    const auto result = create_target(conn)
                        .and_then(read<std::vector<Target>>)
                        .value();

    return result;
}

}  // namespace create_table_as_select
```

