    23→TEST(sqlite, test_create_table_as) {
    24→  using namespace sqlgen;
    25→  using namespace sqlgen::literals;
    26→
    27→  const auto people = std::vector<Person>(
    28→      {Person{
    29→           .id = 0, .first_name = "Homer", .last_name = "Simpson", .age = 45},
    30→       Person{
    31→           .id = 1, .first_name = "Marge", .last_name = "Simpson", .age = 40},
    32→       Person{.id = 2, .first_name = "Bart", .last_name = "Simpson", .age = 10},
    33→       Person{.id = 3, .first_name = "Lisa", .last_name = "Simpson", .age = 8},
    34→       Person{
    35→           .id = 4, .first_name = "Maggie", .last_name = "Simpson", .age = 0}});
    36→
    37→  const auto names_query = select_from<Person>("first_name"_c, "last_name"_c);
    38→
    39→  const auto get_names = create_as<Name>(names_query) | if_not_exists;
    40→
    41→  const auto names = sqlgen::sqlite::connect()
    42→                         .and_then(drop<Name> | if_exists)
    43→                         .and_then(drop<Person> | if_exists)
    44→                         .and_then(write(std::ref(people)))
    45→                         .and_then(get_names)
    46→                         .and_then(sqlgen::read<std::vector<Name>>)
    47→                         .value();
