    52→  const std::string expected =
    53→      R"([{"first_name":"Homer","last_name":"Simpson"},{"first_name":"Marge","last_name":"Simpson"},{"first_name":"Bart","last_name":"Simpson"},{"first_name":"Lisa","last_name":"Simpson"},{"first_name":"Maggie","last_name":"Simpson"}])";
    54→
    55→  EXPECT_EQ(sqlite::to_sql(get_names), expected_query);
